import java.io.BufferedReader; import java.io.InputStreamReader; import java.util.HashMap; import java.util.StringTokenizer; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int n = Integer.parseInt(br.readLine().trim()); StringTokenizer st = new StringTokenizer(br.readLine()); HashMap<Integer, Long> map = new HashMap<>(); map.put(0, 1L); int currentSum = 0; long count = 0; for (int i = 0; i < n; i++) { int val = Integer.parseInt(st.nextToken()); if (val % 2 != 0) { currentSum += 1; } else { currentSum -= 1; } long freq = map.getOrDefault(currentSum, 0L); count += freq; map.put(currentSum, freq + 1); } System.out.println(count); } }